CREATE OR REPLACE FUNCTION public.calculate_organization_renewal_eligibility(_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
DECLARE
  _today date := current_date;
  _org record;
  _acc record;
  _end_date date;
  _days_diff integer;
  _window_status text;
  _can_draft boolean;
  _can_submit boolean;
  _days_until_open integer := NULL;
  _days_past_expiry integer := NULL;
  _reason text;
BEGIN
  SELECT * INTO _org
  FROM public.organization_profiles
  WHERE id = _org_id;

  IF _org.id IS NULL THEN
    RETURN jsonb_build_object(
      'canDraft', false,
      'canSubmit', false,
      'windowStatus', 'too_early',
      'reason', 'Organization profile not found.',
      'daysRemaining', NULL,
      'daysUntilOpen', NULL,
      'daysPastExpiry', NULL,
      'expiresAt', NULL
    );
  END IF;

  -- Resolve authoritative active accreditation term
  SELECT * INTO _acc
  FROM public.organization_accreditations
  WHERE organization_id = _org_id
    AND status = 'active'
  ORDER BY term_number DESC
  LIMIT 1;

  IF _acc.id IS NULL THEN
    IF _org.accreditation_expires_at IS NOT NULL THEN
      _end_date := _org.accreditation_expires_at::date;
    ELSE
      RETURN jsonb_build_object(
        'canDraft', false,
        'canSubmit', false,
        'windowStatus', 'too_early',
        'reason', 'No authoritative accreditation expiration date found.',
        'daysRemaining', NULL,
        'daysUntilOpen', NULL,
        'daysPastExpiry', NULL,
        'expiresAt', NULL
      );
    END IF;
  ELSE
    _end_date := _acc.end_date;
  END IF;

  _days_diff := _end_date - _today;

  -- Authoritative Window Rules:
  -- 1. Window opens: 90 calendar days before expiry
  -- 2. Active Window: [end_date - 90, end_date]
  -- 3. Late Renewal (Grace Period): (end_date, end_date + 180]
  -- 4. Cutoff exceeded (Lapsed): > 180 days past expiry
  IF _days_diff > 90 THEN
    _window_status := 'too_early';
    _can_draft := false;
    _can_submit := false;
    _days_until_open := _days_diff - 90;
    _reason := format('Renewal window opens 90 days before expiry (in %s days).', _days_until_open);
  ELSIF _days_diff >= 0 THEN
    _window_status := 'open';
    _can_draft := true;
    _can_submit := true;
    _reason := 'Renewal window is open.';
  ELSIF ABS(_days_diff) <= 180 THEN
    _window_status := 'expired';
    _can_draft := true;
    _can_submit := true;
    _days_past_expiry := ABS(_days_diff);
    _reason := format('Late renewal allowed within 180 days of expiry (%s days expired).', _days_past_expiry);
  ELSE
    _window_status := 'lapsed';
    _can_draft := false;
    _can_submit := false;
    _days_past_expiry := ABS(_days_diff);
    _reason := 'Late renewal window expired (180 days past expiry). Full re-registration is required.';
  END IF;

  RETURN jsonb_build_object(
    'canDraft', _can_draft,
    'canSubmit', _can_submit,
    'windowStatus', _window_status,
    'daysRemaining', GREATEST(0, _days_diff),
    'daysUntilOpen', _days_until_open,
    'daysPastExpiry', _days_past_expiry,
    'expiresAt', _end_date,
    'reason', _reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_organization_account_canonical(_session_token text, _organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  _admin_id uuid;
  _org public.organization_profiles%rowtype;
  _user_id uuid;
begin
  -- 1. Authorize admin caller
  select vat.admin_id into _admin_id
  from public.validate_admin_session_token(_session_token) vat
  limit 1;

  if _admin_id is null then
    return jsonb_build_object(
      'success', false,
      'stage', 'authorization',
      'error', 'You are not authorized to delete organization accounts.'
    );
  end if;

  -- 2. Lock and load target organization profile
  select * into _org
  from public.organization_profiles
  where id = _organization_id
  for update;

  if not found then
    return jsonb_build_object(
      'success', false,
      'already_deleted', true,
      'stage', 'validation',
      'error', 'Organization profile not found or already deleted.'
    );
  end if;

  _user_id := _org.user_id;

  -- 3. Protection checks: verify target is not an administrator or super admin
  if exists (
    select 1 from public.admin_accounts where lower(trim(email)) = lower(trim(_org.organization_email))
  ) or (_user_id is not null and exists (
    select 1 from public.admin_accounts where id = _user_id
  )) or (_user_id is not null and exists (
    select 1 from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.user_id = _user_id and r.code::text in ('admin', 'super_admin')
  )) then
    return jsonb_build_object(
      'success', false,
      'is_protected', true,
      'stage', 'protection_check',
      'error', 'Administrator accounts cannot be deleted from the YORP Registry.'
    );
  end if;

  perform ytrace_identity.authorize_reviewer(_session_token);
  if ytrace_identity.has_retained_history(_organization_id) then
    raise exception 'Official organization history is retained. Request an authorized archival/retention review before permanent deletion.';
  end if;

  -- 4. Activate transaction-local bypass for immutability triggers
  perform set_config('app.allow_org_deletion', 'true', true);

  -- 5. Disassociate and clean direct Auth dependencies
  if _user_id is not null then
    -- Nullify submitted_by on YPOP to preserve organization historical context without blocking FK
    update public.ypop_entries
    set submitted_by = null
    where submitted_by = _user_id;

    update public.ypop_event_participations
    set submitted_by = null
    where submitted_by = _user_id;

    update public.ypop_org_activities
    set submitted_by = null
    where submitted_by = _user_id;

    -- Clean user specific auxiliary records
    delete from public.user_policy_acceptance where user_id = _user_id;
    delete from public.user_roles where user_id = _user_id;
    delete from public.user_profiles where user_id = _user_id;
  end if;

  -- 6. Clean accreditation and renewal hierarchies safely
  update public.organization_renewals
  set current_accreditation_id = null
  where organization_id = _organization_id;

  delete from public.organization_renewals
  where organization_id = _organization_id;

  delete from public.organization_accreditations
  where organization_id = _organization_id;

  -- 7. Clean document submissions, budget requests, and liquidations
  delete from public.document_submission_files
  where submission_id in (select id from public.document_submissions where organization_id = _organization_id);

  delete from public.document_submissions
  where organization_id = _organization_id;

  delete from public.budget_request_files
  where budget_request_id in (select id from public.budget_requests where organization_id = _organization_id);

  delete from public.budget_requests
  where organization_id = _organization_id;

  delete from public.liquidation_report_files
  where liquidation_report_id in (select id from public.liquidation_reports where organization_id = _organization_id);

  delete from public.liquidation_reports
  where organization_id = _organization_id;

  -- 8. Clean move applications, URN history, and YPOP organization activities
  delete from public.move_files where organization_id = _organization_id;
  delete from public.move_applications where organization_id = _organization_id;
  delete from public.urn_review_history where organization_id = _organization_id;

  delete from public.ypop_files where organization_id = _organization_id;
  delete from public.ypop_event_files where organization_id = _organization_id;
  delete from public.ypop_org_activity_files where organization_id = _organization_id;
  delete from public.ypop_org_activities where organization_id = _organization_id;
  delete from public.ypop_event_participations where organization_id = _organization_id;
  delete from public.ypop_entries where organization_id = _organization_id;

  -- 9. Clean notifications, compliance remarks, inquiries
  delete from public.notifications where organization_id = _organization_id;
  delete from public.compliance_remarks where organization_id = _organization_id;
  delete from public.inquiries where organization_id = _organization_id;

  -- 10. Disassociate historical activity logs without deleting audit trail
  update public.activity_logs
  set organization_id = null
  where organization_id = _organization_id;

  -- 11. Delete organization profile
  delete from public.organization_profiles
  where id = _organization_id;

  -- 12. Verify organization profile is removed
  if exists (select 1 from public.organization_profiles where id = _organization_id) then
    raise exception 'Database deletion failed: organization_profiles row could not be removed.';
  end if;

  return jsonb_build_object(
    'success', true,
    'organization_id', _org.id,
    'organization_name', _org.organization_name,
    'organization_email', _org.organization_email,
    'user_id', _user_id,
    'urn', _org.urn
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_accreditation_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF tg_op = 'UPDATE' THEN
    IF old.term_number IS DISTINCT FROM new.term_number
       OR old.start_date IS DISTINCT FROM new.start_date
       OR old.end_date IS DISTINCT FROM new.end_date
       OR old.certificate_urn IS DISTINCT FROM new.certificate_urn
       OR old.approved_by IS DISTINCT FROM new.approved_by
       OR old.approved_at IS DISTINCT FROM new.approved_at
       OR old.created_at IS DISTINCT FROM new.created_at
       OR old.is_legacy_inferred IS DISTINCT FROM new.is_legacy_inferred THEN

      RAISE EXCEPTION 'Historical accreditation term fields are immutable.';
    END IF;

    -- Revocation immutability rules:
    IF old.revoked_at IS NOT NULL AND new.revoked_at IS DISTINCT FROM old.revoked_at THEN
      RAISE EXCEPTION 'Accreditation revocation timestamp is immutable once set.';
    END IF;

    IF old.revocation_reason IS NOT NULL AND new.revocation_reason IS DISTINCT FROM old.revocation_reason THEN
      RAISE EXCEPTION 'Accreditation revocation reason is immutable once set.';
    END IF;

    IF new.status <> 'revoked' AND new.revoked_at IS NOT NULL THEN
      RAISE EXCEPTION 'Non-revoked accreditation terms cannot have a revocation timestamp.';
    END IF;

    -- Valid status transitions only:
    IF old.status = 'superseded' AND new.status <> 'superseded' THEN
      RAISE EXCEPTION 'A superseded accreditation term cannot be reactivated or altered.';
    END IF;

    IF old.status = 'revoked' AND new.status <> 'revoked' THEN
      RAISE EXCEPTION 'A revoked accreditation term cannot be reactivated.';
    END IF;

    IF old.status <> 'revoked' AND new.status = 'revoked' THEN
      IF new.revoked_at IS NULL THEN
        new.revoked_at := clock_timestamp();
      END IF;
    END IF;

    RETURN new;
  END IF;

  IF tg_op = 'DELETE' THEN
    IF current_setting('app.allow_org_deletion', true) = 'true' THEN
      RETURN old;
    END IF;
    RAISE EXCEPTION 'Accreditation terms in the authoritative ledger cannot be deleted.';
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_renewal_terminal_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF tg_op = 'UPDATE' THEN
    IF old.status IN ('approved', 'rejected') THEN
      RAISE EXCEPTION 'Terminal renewal records cannot be modified.';
    END IF;
    RETURN new;
  END IF;

  IF tg_op = 'DELETE' THEN
    IF current_setting('app.allow_org_deletion', true) = 'true' THEN
      RETURN old;
    END IF;
    IF old.status IN ('approved', 'rejected') THEN
      RAISE EXCEPTION 'Terminal renewal records cannot be deleted.';
    END IF;
    RETURN old;
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.evaluate_and_apply_automatic_registration_verification(_organization_id uuid, _admin_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(verified boolean, urn text, already_verified boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _target_org public.organization_profiles%rowtype;
  _reg_submission_id uuid;
  _required_type_ids uuid[];
  _required_count int;
  _approved_count int;
  _official_urn text;
  _effective_verified_at timestamptz := clock_timestamp();
  _start_date date;
  _end_date date;
  _notify_approved boolean;
begin
  -- 1. Fetch target organization profile
  select *
  into _target_org
  from public.organization_profiles
  where id = _organization_id;

  if _target_org.id is null then
    return query select false, null::text, false, 'Organization profile not found.';
    return;
  end if;

  -- 2. If already verified or suspended, do not re-verify
  if _target_org.profile_status = 'verified' then
    return query select true, _target_org.urn, true, 'Organization is already verified.';
    return;
  end if;

  if _target_org.profile_status = 'suspended_inactive' then
    return query select false, null::text, false, 'Organization is suspended and cannot be verified.';
    return;
  end if;

  -- 3. Resolve parent initial registration document submission (renewal_id is null)
  select id
  into _reg_submission_id
  from public.document_submissions
  where organization_id = _organization_id
    and renewal_id is null
  order by created_at desc
  limit 1;

  if _reg_submission_id is null then
    return query select false, null::text, false, 'No initial registration document submission found.';
    return;
  end if;

  -- 4. Dynamic required document types
  select coalesce(array_agg(rdt.id), '{}'::uuid[])
  into _required_type_ids
  from public.required_document_types rdt
  where rdt.is_active = true
    and coalesce(rdt.is_required, true) = true
    and coalesce(rdt.template_scope, 'document_submission') = 'document_submission'
    and (rdt.scope is null or rdt.scope in ('registration', 'both'))
    and (
      rdt.template_category is null
      or rdt.template_category = '{}'
      or 'yorp' = any(rdt.template_category)
    );

  -- Fallback if no specific registration tags are set
  if array_length(_required_type_ids, 1) is null or array_length(_required_type_ids, 1) = 0 then
    select coalesce(array_agg(rdt.id), '{}'::uuid[])
    into _required_type_ids
    from public.required_document_types rdt
    where rdt.is_active = true;
  end if;

  _required_count := coalesce(array_length(_required_type_ids, 1), 0);

  if _required_count = 0 then
    return query select false, null::text, false, 'No active required document types configured in system.';
    return;
  end if;

  -- 5. Count approved files for required document types
  select count(distinct dsf.document_type_id)
  into _approved_count
  from public.document_submission_files dsf
  where dsf.submission_id = _reg_submission_id
    and dsf.document_type_id = any(_required_type_ids)
    and dsf.admin_status = 'approved_green';

  -- If any required document type is not approved, block verification
  if _approved_count < _required_count then
    return query select false, null::text, false,
      format('Incomplete: %s of %s required registration documents approved.', _approved_count, _required_count);
    return;
  end if;

  -- 6. ALL REQUIRED REGISTRATION DOCUMENTS ARE APPROVED -> PROCEED WITH AUTOMATIC VERIFICATION
  _start_date := date(_effective_verified_at);
  _end_date := (_start_date + interval '3 years')::date;

  -- Preserve existing URN if already present, otherwise generate deterministic official URN (BB-YY-NNN)
  if _target_org.urn is not null and trim(_target_org.urn) <> '' then
    _official_urn := trim(_target_org.urn);
  elsif _target_org.is_existing_organization and _target_org.organization_identifier_number is not null and trim(_target_org.organization_identifier_number) <> '' then
    _official_urn := trim(_target_org.organization_identifier_number);
  else
    _official_urn := public.generate_unique_urn(_target_org.barangay, _effective_verified_at);
  end if;

  -- 7. Update organization profile with official verified status and assigned URN (using actual schema)
  update public.organization_profiles
  set
    profile_status = 'verified'::public.profile_status,
    verified_at = _effective_verified_at,
    urn = _official_urn,
    urn_normalized = public.normalize_urn(_official_urn),
    organization_identifier_number = _official_urn,
    urn_review_status = 'verified'::public.urn_review_status,
    verification_method = coalesce(_target_org.verification_method, 'documents'::public.verification_method),
    updated_at = _effective_verified_at
  where id = _organization_id;

  -- 8. Create Term 1 accreditation record if not already present
  if not exists (
    select 1 from public.organization_accreditations
    where organization_id = _organization_id and term_number = 1
  ) then
    insert into public.organization_accreditations (
      organization_id,
      term_number,
      start_date,
      end_date,
      certificate_urn,
      status,
      is_legacy_inferred,
      approved_by,
      approved_at,
      created_at
    ) values (
      _organization_id,
      1,
      _start_date,
      _end_date,
      _official_urn,
      'active',
      false,
      _admin_id,
      _effective_verified_at,
      _effective_verified_at
    );
  end if;

  -- 9. Canonical Activity Log
  insert into public.activity_logs (
    actor_user_id,
    organization_id,
    action,
    related_type,
    related_id,
    description,
    created_at
  ) values (
    _admin_id,
    _organization_id,
    'Verified organization registration',
    'organization_profile',
    _organization_id,
    format('Organization registration verified automatically upon approval of all required documents. Assigned URN: %s (Valid until %s).', _official_urn, _end_date),
    _effective_verified_at
  );

  -- 10. Gated In-App Notification based on workflow.notify_org_on_approved
  _notify_approved := public.get_system_setting_bool('workflow.notify_org_on_approved', true);
  if _target_org.user_id is not null and _notify_approved then
    insert into public.notifications (
      user_id,
      organization_id,
      title,
      message,
      type,
      related_type,
      related_id,
      created_at
    ) values (
      _target_org.user_id,
      _organization_id,
      'Registration Approved & Verified',
      format('Congratulations! Your organization registration has been approved and verified. Your official URN is %s.', _official_urn),
      'completed',
      'organization_profile',
      _organization_id,
      _effective_verified_at
    );
  end if;

  return query select true, _official_urn, false, 'Registration successfully verified.';
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_renewal_test_registration_packet_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _submission_id uuid;
  _is_seeded_registration boolean := false;
BEGIN
  IF TG_TABLE_NAME = 'document_submission_files'
     AND TG_OP = 'INSERT'
     AND current_setting('app.seed_renewal_test_registration_documents', true) = 'true' THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'document_submissions' THEN
    _submission_id := OLD.id;
    _is_seeded_registration :=
      OLD.is_seeded_sample_data IS TRUE
      AND OLD.seed_batch = 'RENEWAL-TEST-REGISTRATION'
      AND OLD.submission_scope = 'registration'
      AND OLD.renewal_id IS NULL;
  ELSE
    IF TG_OP = 'INSERT' THEN
      _submission_id := NEW.submission_id;
    ELSE
      _submission_id := OLD.submission_id;
    END IF;
    SELECT EXISTS (
      SELECT 1
      FROM public.document_submissions submission
      WHERE (submission.id = _submission_id
         OR (TG_OP = 'UPDATE' AND submission.id = NEW.submission_id))
        AND submission.is_seeded_sample_data IS TRUE
        AND submission.seed_batch = 'RENEWAL-TEST-REGISTRATION'
        AND submission.submission_scope = 'registration'
        AND submission.renewal_id IS NULL
    ) INTO _is_seeded_registration;
  END IF;

  IF _is_seeded_registration THEN
    RAISE EXCEPTION 'The Renewal Test Organization registration packet is an immutable Cycle 1 record.';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_submitted_registration_document_edits()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  _submission_status text;
  _registration_submission boolean;
begin
  -- Admin and correction RPCs run with their validated definer privileges.
  if current_user not in ('authenticated', 'anon')
     or public.current_user_is_admin() then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  select ds.status,
         ds.submission_scope = 'registration' and ds.renewal_id is null
    into _submission_status, _registration_submission
  from public.document_submissions ds
  where ds.id = old.submission_id
  for update;

  if old.admin_status is distinct from 'draft'
     or _submission_status is null
     or not (
       _submission_status in ('draft', 'needs_revision')
       or (
         _registration_submission is true
         and _submission_status in ('under_admin_review', 'submitted', 'ready_for_review')
       )
     ) then
    raise exception 'Submitted documents are locked. Only draft documents can be edited or removed; requested revisions must use the replacement flow.';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.user_replace_document_submission_file(_file_id uuid, _new_file_url text, _new_file_name text, _new_file_type text, _new_file_size numeric DEFAULT NULL::numeric, _submit_for_review boolean DEFAULT true)
 RETURNS document_submission_files
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _old_file record;
  _submission record;
  _owner_id uuid;
  _history jsonb;
  _history_entry jsonb;
  _updated_row public.document_submission_files;
BEGIN
  SELECT * INTO _old_file
  FROM public.document_submission_files
  WHERE id = _file_id;

  IF _old_file.id IS NULL THEN
    RAISE EXCEPTION 'Document file not found.';
  END IF;

  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE id = _old_file.submission_id;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'Parent document submission not found.';
  END IF;

  SELECT user_id INTO _owner_id
  FROM public.organization_profiles
  WHERE id = _submission.organization_id;

  IF _owner_id <> auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this submission.';
  END IF;

  _history_entry := jsonb_build_object(
    'action', 'replaced',
    'previousFileName', _old_file.file_name,
    'previousFileUrl', _old_file.file_url,
    'previousFileType', _old_file.file_type,
    'previousFileSize', _old_file.file_size,
    'previousStatus', _old_file.admin_status,
    'adminRemarks', _old_file.admin_remarks,
    'reviewedAt', _old_file.reviewed_at,
    'replacedAt', clock_timestamp()
  );

  _history := coalesce(_old_file.revision_history, '[]'::jsonb) || jsonb_build_array(_history_entry);

  UPDATE public.document_submission_files
  SET
    file_url = _new_file_url,
    file_name = _new_file_name,
    file_type = _new_file_type,
    file_size = coalesce(_new_file_size, _old_file.file_size),
    admin_status = CASE
      WHEN _submit_for_review THEN 'submitted'::public.document_submission_status
      ELSE 'draft'::public.document_submission_status
    END,
    admin_remarks = NULL,
    reviewed_at = NULL,
    uploaded_at = clock_timestamp(),
    updated_at = clock_timestamp(),
    revision_history = _history
  WHERE id = _file_id
  RETURNING * INTO _updated_row;

  RETURN _updated_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.user_resubmit_renewal(p_renewal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _renewal record;
  _submission record;
  _owner_id uuid;
  _end_date date;
  _now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF _renewal.id IS NULL THEN
    RAISE EXCEPTION 'Renewal application not found.';
  END IF;

  SELECT op.user_id INTO _owner_id
  FROM public.organization_profiles op
  WHERE op.id = _renewal.organization_id;

  IF _owner_id <> auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _renewal.status <> 'needs_revision' THEN
    RAISE EXCEPTION 'Renewal cannot be resubmitted from status "%". Expected "needs_revision".', _renewal.status;
  END IF;

  -- Verify within 180-day window
  SELECT oa.end_date INTO _end_date
  FROM public.organization_accreditations oa
  WHERE oa.id = _renewal.current_accreditation_id;

  IF current_date > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal cutoff has passed (180 days past expiration). Resubmission is no longer allowed.';
  END IF;

  -- Verify all flagged documents have been replaced
  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE renewal_id = p_renewal_id
  FOR UPDATE;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'No document submission packet found for this renewal.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.document_submission_files dsf
    WHERE dsf.submission_id = _submission.id
      AND dsf.admin_status IN ('needs_revision', 'rejected_red')
  ) THEN
    RAISE EXCEPTION 'All documents marked for revision or rejection must be replaced before resubmission.';
  END IF;

  -- Update renewal state to resubmitted
  UPDATE public.organization_renewals
  SET
    status = 'resubmitted',
    updated_at = _now
  WHERE id = p_renewal_id;

  -- Update document submission state
  UPDATE public.document_submissions
  SET
    status = 'submitted',
    updated_at = _now
  WHERE id = _submission.id;

  -- Insert activity log with NULL actor_user_id (org user action)
  INSERT INTO public.activity_logs (
    actor_user_id,
    organization_id,
    action,
    related_type,
    related_id,
    description
  ) VALUES (
    NULL,
    _renewal.organization_id,
    'renewal_resubmitted',
    'renewal',
    p_renewal_id,
    format('Organization resubmitted renewal application for Cycle %s after revisions.', _renewal.cycle_number)
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'resubmitted_at', _now
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.user_start_or_get_renewal_draft(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller_id uuid;
  _profile record;
  _curr_acc record;
  _existing_renewal record;
  _submission record;
  _today date := current_date;
  _end_date date;
  _target_cycle integer;
  _new_renewal record;
  _new_submission record;
BEGIN
  _caller_id := auth.uid();
  IF _caller_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: Authentication required.';
  END IF;

  -- Lock organization profile to serialize draft creation
  SELECT op.id, op.user_id, op.profile_status, op.current_accreditation_id, op.accreditation_expires_at
  INTO _profile
  FROM public.organization_profiles op
  WHERE op.id = p_organization_id
  FOR UPDATE;

  IF _profile.id IS NULL THEN
    RAISE EXCEPTION 'Organization profile not found.';
  END IF;

  IF _profile.user_id <> _caller_id THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _profile.profile_status <> 'verified' THEN
    RAISE EXCEPTION 'Organization must have verified profile status to initiate renewal.';
  END IF;

  -- Resolve authoritative accreditation term
  SELECT oa.*
  INTO _curr_acc
  FROM public.organization_accreditations oa
  WHERE oa.id = _profile.current_accreditation_id
    AND oa.organization_id = p_organization_id
  LIMIT 1;

  IF _curr_acc.id IS NULL THEN
    SELECT oa.*
    INTO _curr_acc
    FROM public.organization_accreditations oa
    WHERE oa.organization_id = p_organization_id
      AND oa.status = 'active'
    ORDER BY oa.term_number DESC
    LIMIT 1;
  END IF;

  IF _curr_acc.id IS NULL THEN
    RAISE EXCEPTION 'No authoritative accreditation term found for this organization.';
  END IF;

  IF _curr_acc.status = 'revoked' THEN
    RAISE EXCEPTION 'Accreditation has been revoked. Organization cannot renew and must contact LYDO.';
  END IF;

  _end_date := _curr_acc.end_date;

  -- Verify renewal window: [end_date - 90 days, end_date + 180 days]
  IF _today < (_end_date - 90) THEN
    RAISE EXCEPTION 'Renewal window is not yet open. Renewals open 90 days prior to expiration (on %).', (_end_date - 90);
  END IF;

  IF _today > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal window has expired (180 days past expiration). Full re-registration is required.';
  END IF;

  -- Check if a non-terminal renewal is already in progress
  SELECT *
  INTO _existing_renewal
  FROM public.organization_renewals
  WHERE organization_id = p_organization_id
    AND status IN ('draft', 'submitted', 'under_review', 'needs_revision', 'resubmitted')
  ORDER BY cycle_number DESC
  LIMIT 1;

  IF _existing_renewal.id IS NOT NULL THEN
    SELECT * INTO _submission
    FROM public.document_submissions
    WHERE renewal_id = _existing_renewal.id
    LIMIT 1;

    RETURN jsonb_build_object(
      'renewal', row_to_json(_existing_renewal),
      'submission', row_to_json(_submission),
      'is_existing', true
    );
  END IF;

  -- Calculate target cycle number (strictly current_term.term_number + 1)
  _target_cycle := _curr_acc.term_number + 1;

  -- Verify no terminal rejected renewal exists for this cycle
  IF EXISTS (
    SELECT 1 FROM public.organization_renewals
    WHERE organization_id = p_organization_id
      AND cycle_number = _target_cycle
      AND status = 'rejected'
  ) THEN
    RAISE EXCEPTION 'Renewal application for Cycle % was rejected. Organization must contact LYDO directly.', _target_cycle;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.organization_renewals
    WHERE organization_id = p_organization_id
      AND cycle_number = _target_cycle
      AND status = 'approved'
  ) THEN
    RAISE EXCEPTION 'Cycle % is already approved.', _target_cycle;
  END IF;

  -- Create single draft renewal application
  INSERT INTO public.organization_renewals (
    organization_id,
    cycle_number,
    current_accreditation_id,
    status
  ) VALUES (
    p_organization_id,
    _target_cycle,
    _curr_acc.id,
    'draft'
  ) RETURNING * INTO _new_renewal;

  -- Create single linked document submission packet
  INSERT INTO public.document_submissions (
    organization_id,
    submitted_by,
    status,
    user_confirmed,
    submission_scope,
    renewal_id
  ) VALUES (
    p_organization_id,
    _caller_id,
    'draft',
    false,
    'renewal',
    _new_renewal.id
  ) RETURNING * INTO _new_submission;

  RETURN jsonb_build_object(
    'renewal', row_to_json(_new_renewal),
    'submission', row_to_json(_new_submission),
    'is_existing', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.user_submit_renewal(p_renewal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _renewal record;
  _submission record;
  _owner_id uuid;
  _end_date date;
  _now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF _renewal.id IS NULL THEN
    RAISE EXCEPTION 'Renewal application not found.';
  END IF;

  SELECT op.user_id INTO _owner_id
  FROM public.organization_profiles op
  WHERE op.id = _renewal.organization_id;

  IF _owner_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _renewal.status <> 'draft' THEN
    RAISE EXCEPTION 'Renewal cannot be submitted from status "%". Expected "draft".', _renewal.status;
  END IF;

  SELECT oa.end_date INTO _end_date
  FROM public.organization_accreditations oa
  WHERE oa.id = _renewal.current_accreditation_id;

  IF current_date > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal cutoff has passed (180 days past expiration). Application can no longer be submitted.';
  END IF;

  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE renewal_id = p_renewal_id
  FOR UPDATE;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'No renewal document submission found.';
  END IF;

  -- Each selected document may be sent as it is ready. The admin approval RPC
  -- continues to enforce completeness and approval of every required type.
  IF NOT EXISTS (
    SELECT 1
    FROM public.document_submission_files dsf
    JOIN public.required_document_types rdt ON rdt.id = dsf.document_type_id
    WHERE dsf.submission_id = _submission.id
      AND rdt.is_active = true
      AND coalesce(rdt.is_required, true) = true
      AND rdt.scope IN ('renewal', 'both')
      AND rdt.template_scope = 'document_submission'
      AND nullif(trim(dsf.file_url), '') IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Upload at least one required renewal document before submitting.';
  END IF;

  UPDATE public.organization_renewals
  SET status = 'submitted', submitted_at = _now, updated_at = _now
  WHERE id = p_renewal_id;

  UPDATE public.document_submissions
  SET status = 'submitted', submitted_at = _now, updated_at = _now
  WHERE id = _submission.id;

  INSERT INTO public.activity_logs (
    actor_user_id, organization_id, action, related_type, related_id, description
  ) VALUES (
    NULL,
    _renewal.organization_id,
    'renewal_submitted',
    'renewal',
    p_renewal_id,
    format('Organization submitted renewal documents for Cycle %s.', _renewal.cycle_number)
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'submitted_at', _now
  );
END;
$function$

CREATE OR REPLACE FUNCTION ytrace_production_containment.freeze_fixture_markers()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF coalesce(NEW.is_seeded_sample_data,false) OR NEW.seed_batch IS NOT NULL THEN
      RAISE EXCEPTION 'Production fixture markers cannot be created.' USING ERRCODE='42501';
    END IF;
  ELSIF ROW(NEW.is_seeded_sample_data,NEW.seed_batch) IS DISTINCT FROM ROW(OLD.is_seeded_sample_data,OLD.seed_batch) THEN
    RAISE EXCEPTION 'Production fixture markers are immutable.' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$function$
